"""Package unaltered 1600px renders as high-quality JPEG photos and an inspection gallery."""
from pathlib import Path
import subprocess,zipfile,json,hashlib
ROOT=Path(__file__).resolve().parents[1];PROJECT=ROOT.parents[1];dest=PROJECT/'public/assets/aurelia-photos';dest.mkdir(parents=True,exist_ok=True)
angles=['front_right','front_left','rear_right','rear_left'];sides=['front','back','left','right'];details=['beauty','top','cockpit','engine','gear'];orbit=['orbit_'+str(i).zfill(3) for i in range(0,360,30)]
names=angles+sides+details+orbit
for name in names:
    source=ROOT/'renders'/f'{name}.png';assert source.is_file(),source
    subprocess.run(['sips','-s','format','jpeg','-s','formatOptions','94',str(source),'--out',str(dest/f'{name}.jpg')],check=True,capture_output=True)
with zipfile.ZipFile(PROJECT/'public/assets/Aurelia-S32-photos.zip','w',zipfile.ZIP_DEFLATED) as archive:
    for name in names:archive.write(dest/f'{name}.jpg',f'Aurelia-S32/{name}.jpg')
def grid(items):
    return '<div class="grid">'+''.join(f'<a href="/assets/aurelia-photos/{n}.jpg" target="_blank"><figure><img loading="lazy" src="/assets/aurelia-photos/{n}.jpg" alt="Aurelia S32 — {n.replace("_"," ")}"><figcaption>{n.replace("_"," ").title()} <span>↗ Full-size photo</span></figcaption></figure></a>' for n in items)+'</div>'
report=json.loads((ROOT/'validation/roundtrip.json').read_text());assert report['status']=='passed'
sha=hashlib.sha256((PROJECT/'public/assets/aurelia-s32.glb').read_bytes()).hexdigest()
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="/favicon.svg"><title>Aurelia S32 · 360° inspection photos</title><style>*{box-sizing:border-box}body{margin:0;background:#f2f3ed;color:#26444b;font:15px/1.7 system-ui}main{max-width:1160px;margin:auto;padding:38px 28px 70px}a{color:inherit}nav{display:flex;gap:25px;flex-wrap:wrap;font-size:12px;margin-bottom:50px}header{max-width:820px}h1{font:56px Georgia;margin:18px 0}h2{font:31px Georgia;margin:48px 0 20px}p{color:#6a7e7b}.label{font-size:10px;letter-spacing:2px}button{font:inherit;color:inherit;cursor:pointer;border:1px solid #b3c3bc;border-radius:7px;background:#fafaf4;padding:7px 15px}a{text-decoration:none}a:hover{text-decoration:underline}.orbit{background:#d9dfda;border-radius:16px;overflow:hidden}.orbit img{display:block;width:100%;aspect-ratio:16/11;object-fit:contain}.orbit-controls{display:flex;align-items:center;gap:20px;padding:18px 24px;background:#e4e8df}.orbit-controls input{flex:1;accent-color:#315b61}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.grid a{background:#fff;border-radius:12px;overflow:hidden}.grid figure{margin:0}.grid img{display:block;width:100%;aspect-ratio:16/11;object-fit:cover}.grid figcaption{padding:14px 18px;font-size:13px}.grid span{float:right;font-size:11px;color:#879590}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:14px 10px;text-align:left;border-bottom:1px solid #cfd8ce;vertical-align:top}th{color:#6b807a}.note{font-size:12px}.metadata{font-size:10px;overflow-wrap:anywhere;color:#83918a;margin-top:44px}@media(max-width:620px){h1{font-size:42px}main{padding:25px 18px}.grid{grid-template-columns:1fr}.orbit-controls{gap:10px;padding:12px}.orbit-controls button{font-size:11px}.grid span{display:none}}</style></head><body><main><nav><a href="/civilian.html">↖ Interactive 3D aircraft</a><a href="/assets/Aurelia-S32-photos.zip" download>Download all 25 photos ↓</a><a href="/assets/aurelia-s32.glb" download>Download 3D model ↓</a></nav><header><div class="label">AIRCRAFT ATELIER / 003 · FINAL MODEL INSPECTION</div><h1>Aurelia, from every side.</h1><p>An original civilian executive jet with a broad pressure cabin, swept wings and winglets, twin rear-mounted turbofans, a pearl finish and Atlantic-blue lower fuselage. These photographs are rendered directly from the finished 3D aircraft.</p></header><h2>360° photo orbit</h2><div class="orbit"><img id="orbit-photo" src="/assets/aurelia-photos/orbit_000.jpg" alt="Aurelia S32 orbit, 0 degrees"><div class="orbit-controls"><button id="play" aria-pressed="false">Play orbit</button><input id="angle" aria-label="Photo orbit angle" type="range" min="0" max="11" step="1" value="0"><output id="degrees">0°</output></div></div><p class="note">Twelve photographs at 30° intervals cover the complete aircraft. Use the interactive 3D view for continuous rotation, zooming and control-surface inspection.</p><h2>Four three-quarter angles</h2>'''+grid(angles)+'''<h2>Four sides</h2>'''+grid(sides)+'''<h2>Silhouette and details</h2>'''+grid(details)+'''<h2>Inspection findings and corrections</h2><table><thead><tr><th>Area checked</th><th>Final result</th></tr></thead><tbody><tr><td>Lower fuselage</td><td>Reshaped the cabin floor to follow the interior hull section, removing the plate that protruded below the passenger door and aft cabin.</td></tr><tr><td>Wing roots</td><td>Removed the overlapping fairing skin. The swept wing now enters the body cleanly without the raised triangular overlap.</td></tr><tr><td>Window surrounds</td><td>Applied shape-based shell normals to reduce boolean shading dents, and refined the glazing tint. All 16 cabin apertures remain separate modeled windows.</td></tr><tr><td>Tail and markings</td><td>Verified the rudder on the centreline and moved the civilian registration clear of the intake surround.</td></tr><tr><td>Landing gear</td><td>Six tires checked against the ground plane after GLB round-trip; each is within 12 mm of ground contact. Separate wheel and steering parents retained.</td></tr><tr><td>Engines and symmetry</td><td>Both intake axes have 0.82 m clearance to the spinner. Left and right wing bounds match within 10 mm. Separate fans, flaps, ailerons, elevators and rudder verified.</td></tr></tbody></table><p class="note">Visual and geometry checks apply to this 3D asset. This Aurelia page is an aircraft model viewer; the existing Pocket Flight game continues to offer Finch and Peregrine.</p><div class="metadata">MODEL SHA-256: '''+sha+'''<br>25 rendered photographs · 1600 × 1100 pixels · Blender Cycles · September 8, 2026</div></main><script>const range=document.querySelector('#angle'),photo=document.querySelector('#orbit-photo'),degrees=document.querySelector('#degrees'),play=document.querySelector('#play');let timer=null;function show(){const a=Number(range.value)*30;photo.src='/assets/aurelia-photos/orbit_'+String(a).padStart(3,'0')+'.jpg';photo.alt='Aurelia S32 orbit, '+a+' degrees';degrees.value=a+'°';}range.oninput=show;function stop(){clearInterval(timer);timer=null;play.textContent='Play orbit';play.setAttribute('aria-pressed','false');}play.onclick=()=>{if(timer){stop();return;}timer=setInterval(()=>{range.value=(Number(range.value)+1)%12;show();},900);play.textContent='Pause';play.setAttribute('aria-pressed','true');};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});</script></body></html>'''
(PROJECT/'public/aurelia-inspection.html').write_text(html)
print('Packaged',len(names),'photos; inspection gallery ready')
